package service
import("context";"fmt";"strconv";"github.com/google/uuid";"github.com/jackc/pgx/v5";"github.com/jackc/pgx/v5/pgxpool";shopeeint "github.com/openoms-org/openoms/apps/api-server/internal/integration/shopee";"github.com/openoms-org/openoms/apps/api-server/internal/database";"github.com/openoms-org/openoms/apps/api-server/internal/repository";shopeesdk "github.com/openoms-org/openoms/packages/shopee-go-sdk")
type ShopeeProviderResolver func(context.Context,pgx.Tx,uuid.UUID)(*shopeeint.Provider,error)
type ShopeeStockPushService struct{pool *pgxpool.Pool;stock *repository.WarehouseStockRepository;mappings *repository.MarketplaceSKUMappingRepository;resolve ShopeeProviderResolver}
func NewShopeeStockPushService(pool *pgxpool.Pool,resolve ShopeeProviderResolver)*ShopeeStockPushService{return &ShopeeStockPushService{pool:pool,stock:repository.NewWarehouseStockRepository(),mappings:repository.NewMarketplaceSKUMappingRepository(),resolve:resolve}}
func(s *ShopeeStockPushService)PushCanonical(ctx context.Context,tenantID,productID uuid.UUID,variantID *uuid.UUID)error{return database.WithTenant(ctx,s.pool,tenantID,func(tx pgx.Tx)error{stocks,err:=s.stock.ListByProduct(ctx,tx,productID);if err!=nil{return err};available:=0;for _,st:=range stocks{if variantID==nil&&st.VariantID!=nil{continue};if variantID!=nil&&(st.VariantID==nil||*st.VariantID!=*variantID){continue};v:=st.Quantity-st.Reserved;if v>0{available+=v}};maps,err:=s.mappings.ListByCanonical(ctx,tx,productID,variantID);if err!=nil{return err};for _,m:=range maps{if m.Provider!="shopee"{continue};itemID,err:=strconv.ParseInt(m.ExternalItemID,10,64);if err!=nil{return fmt.Errorf("invalid Shopee item id: %w",err)};modelID:=int64(0);if m.ExternalModelID!=""{modelID,err=strconv.ParseInt(m.ExternalModelID,10,64);if err!=nil{return fmt.Errorf("invalid Shopee model id: %w",err)}};p,err:=s.resolve(ctx,tx,m.IntegrationID);if err!=nil{return err};if err:=p.SDKClient().UpdateStock(ctx,p.AccessToken(),p.ShopID(),itemID,[]shopeesdk.StockUpdate{{ModelID:modelID,NormalStock:available}});err!=nil{return err}};return nil})}
